def S(P):
    """A fixed frame as a frame function."""
    return lambda r: P


# =========================================================== 0549 skill factories

def matching(t, frames):
    """शीर्षक मिलाना. frame: dict(kind, intro_title, paras=[(text, heading)], extra=[unused headings], why={i: reason})."""

    def lay(P):
        txt = '\n'.join(f'अनुच्छेद {i + 1}: {p}' for i, (p, h) in enumerate(P['paras']))
        return f'नीचे “{P["title"]}” विषय पर एक {P["kind"]} दिया गया है।\n{txt}\n'

    def heads(r, P):
        hs = [h for _, h in P['paras']] + list(P['extra'])
        r.shuffle(hs)
        return hs

    @t.add('C1', (1, 2, 3))
    def mt_c1(r, D):
        P = r.choice(frames)(r)
        i = r.randrange(len(P['paras']))
        h = P['paras'][i][1]
        ds = [x for _, x in P['paras'] if x != h] + list(P['extra'])
        return mq(r, lay(P) + f'अनुच्छेद {i + 1} के लिए सबसे उपयुक्त शीर्षक कौन-सा है?', h, others(r, ds, h, 3), P['why'].get(i, 'अनुच्छेद का मुख्य विषय यही है।'))

    @t.add('C2', (1, 2, 3, 4), 'explain')
    def mt_c2(r, D):
        P = r.choice(frames)(r)
        m = mk('C2', D)
        i = r.randrange(len(P['paras']))
        h = P['paras'][i][1]
        if r.random() < 0.5 and P['extra']:
            wrong = r.choice(P['extra'])
            n, g = name(r)
            stem = lay(P) + f'{n} ने अनुच्छेद {i + 1} के लिए शीर्षक {Q(wrong)} चुना। यह उपयुक्त क्यों नहीं है? सही शीर्षक बताइए' + (' और अनुच्छेद से प्रमाण दीजिए।' if m >= 2 else '। उत्तर संक्षेप में दीजिए।')
            ans = f'{Q(wrong)} अनुच्छेद के मुख्य विषय से मेल नहीं खाता। सही शीर्षक: {Q(h)}। {P["why"].get(i, "")}'
        else:
            stem = lay(P) + f'शीर्षक {Q(h)} किस अनुच्छेद के लिए उपयुक्त है? अपने उत्तर का कारण दीजिए।'
            ans = f'अनुच्छेद {i + 1}। {P["why"].get(i, "")}'
        return item(stem, ans, 'सही अनुच्छेद/शीर्षक (1)' + ('; अनुच्छेद से प्रमाण (1)' if m >= 2 else '') + ('; मुख्य विषय और विवरण में अंतर स्पष्ट (1)' if m >= 3 else ''), m, 'explain')

    @t.add('C3', (1, 2, 3, 4, 5), 'short')
    def mt_c3(r, D):
        P = r.choice(frames)(r)
        hs = heads(r, P)
        lst = ' / '.join(Q(h) for h in hs)
        parts = [(f'अनुच्छेद {i + 1} के लिए शीर्षक चुनिए।', h, f'{h} [1]') for i, (_, h) in enumerate(P['paras'])]
        parts.append(('कौन-सा शीर्षक किसी भी अनुच्छेद के लिए उपयुक्त नहीं है? कारण दीजिए।', ', '.join(P['extra']) + ' — यह किसी अनुच्छेद के मुख्य विषय से मेल नहीं खाता।', 'अतिरिक्त शीर्षक (1); कारण (1) [2]'))
        return hcompose(r, lay(P) + f'शीर्षक: {lst}\nनिर्देशानुसार उत्तर दीजिए।', parts, k=(2, 3, 4))

    @t.add('C4', (2, 3, 4, 5), 'multi_step')
    def mt_c4(r, D):
        P = r.choice(frames)(r)
        m = mk('C4', D)
        k = len(P['paras'])
        stem = lay(P) + r.choice([f'प्रत्येक अनुच्छेद के लिए अपना एक छोटा शीर्षक (अधिकतम पाँच शब्द) बनाइए और बताइए कि वह उस अनुच्छेद के मुख्य विचार को कैसे दर्शाता है। अंत में पूरे {P["kind"]} के लिए एक मुख्य शीर्षक सुझाइए।',
                                  f'प्रत्येक अनुच्छेद का मुख्य विचार एक वाक्य में लिखिए। फिर बताइए कि शीर्षक मिलाते समय मुख्य विचार और छोटे विवरण में अंतर करना क्यों ज़रूरी है।'])
        ans = ' '.join(f'अनुच्छेद {i + 1}: {h} — {P["why"].get(i, "")}' for i, (_, h) in enumerate(P['paras']))
        key = f'प्रत्येक अनुच्छेद का सही मुख्य विचार/शीर्षक (लगभग {max(1, (m - 1) // k)} अंक प्रति अनुच्छेद); अंतिम भाग (1)। अपेक्षित: ' + '; '.join(h for _, h in P['paras']) + f'। [{m}]'
        return item(stem, ans, key, m, 'multi_step')


def notes_extra(t, frames, mode='read'):
    """Extra note-making items (0549 Exercise 3 style). frames need 'notes'."""

    @t.add('C1', (1, 2, 3))
    def nt_c1(r, D):
        P = frame_of(r, frames, mode)
        hs = list(P['notes'])
        h = r.choice(hs)
        good = r.choice(P['notes'][h])
        bad = [x for hh in hs if hh != h for x in P['notes'][hh]]
        if len(bad) < 3:
            return None
        return mq(r, head(P) + f'नोट्स बनाते समय शीर्षक {Q(h)} के अंतर्गत कौन-सा बिंदु आएगा?', good, others(r, bad, good, 3), f'यह बिंदु “{h}” से संबंधित है; बाकी दूसरे शीर्षकों के बिंदु हैं।')

    @t.add('C3', (1, 2, 3, 4, 5), 'short')
    def nt_c3(r, D):
        P = frame_of(r, frames, mode)
        parts = []
        for h, pts in P['notes'].items():
            k = min(2, len(pts))
            parts.append((f'शीर्षक {Q(h)} के अंतर्गत {"दो बिंदु" if k == 2 else "एक बिंदु"} लिखिए।', '; '.join(pts), f'कोई {k} सही बिंदु (1 प्रत्येक) [{k}]'))
        return hcompose(r, head(P) + 'इस पाठ के आधार पर नोट्स पूरे कीजिए। बिंदु छोटे वाक्यांशों में लिखिए।', parts, k=(2, 3))


def summary_extra(t, frames, mode='read'):
    """Extra summary items (0549 Exercise 4 style). frames need 'points'."""

    @t.add('C1', (1, 2, 3))
    def sm_c1(r, D):
        P = frame_of(r, frames, mode)
        good = P['gist']
        pool = [f(r).get('gist') for f in frames]
        ds = [x for x in pool if x and x != good] + ['पाठ में केवल आँकड़ों की सूची दी गई है।', 'पाठ का मुख्य विषय लेखक की निजी यात्रा है।']
        return mq(r, head(P) + 'इनमें से कौन-सा वाक्य इस पाठ का सबसे अच्छा सारांश है?', good, others(r, ds, good, 3), 'यह वाक्य पाठ के मुख्य विचार को समेटता है; बाकी या तो अधूरे हैं या दूसरे पाठ के हैं।')

    @t.add('C2', (1, 2, 3, 4), 'explain')
    def sm_c2(r, D):
        P = frame_of(r, frames, mode)
        m = mk('C2', D)
        pts = P['points']
        k = 2 if m <= 2 else 3
        stem = head(P) + f'सारांश लिखने के लिए इस पाठ से {k} सबसे महत्वपूर्ण बिंदु चुनिए और बताइए कि उदाहरण या आँकड़े सारांश में क्यों नहीं लिखे जाते।'
        return item(stem, '; '.join(pts[:k + 1]) + '। सारांश में मुख्य विचार अपने शब्दों में लिखे जाते हैं; उदाहरण/आँकड़े केवल विस्तार हैं।', f'प्रत्येक मुख्य बिंदु (1); उदाहरण छोड़ने का कारण (शेष अंक)। मुख्य बिंदु: ' + '; '.join(pts), m, 'explain')


