# =========================================================== इकाई 1: मैं, मेरा परिवार और दोस्त

def rd_profile1(r):
    n, g = name(r, 'f')
    c, ctry = r.choice([('दुबई', 'संयुक्त अरब अमीरात'), ('लंदन', 'इंग्लैंड'), ('टोरंटो', 'कनाडा'), ('सिंगापुर', 'सिंगापुर')])
    age = r.choice([14, 15])
    text = (f'नमस्ते! मेरा नाम {n} है और मैं {age} साल की हूँ। मेरा जन्म जयपुर में हुआ था, पर पिछले छह साल से मैं अपने परिवार के साथ {c} में रहती हूँ। '
            f'हमारे परिवार में पाँच लोग हैं — मम्मी, पापा, मेरा छोटा भाई, दादी और मैं। पापा एक अस्पताल में इंजीनियर हैं और मम्मी घर से ही ऑनलाइन हिंदी पढ़ाती हैं। '
            f'मेरा भाई बहुत शरारती है, पर दिल का बहुत अच्छा है; जब मैं उदास होती हूँ तो वह मुझे चुटकुले सुनाकर हँसा देता है। '
            f'दादी हमारे घर की जान हैं। वे रोज़ शाम को हमें राजस्थान की लोककथाएँ सुनाती हैं। मुझे चित्र बनाना और बैडमिंटन खेलना पसंद है। '
            f'मेरी सबसे अच्छी सहेली मरियम है, जो मिस्र से है। हम दोनों एक-दूसरे को अपनी भाषा के शब्द सिखाती हैं — उसने मुझे अरबी में “शुक्रान” कहना सिखाया और मैंने उसे “धन्यवाद”!')
    return ex('व्यक्तिगत परिचय', text,
              facts=[(f'{n} का जन्म कहाँ हुआ था?', 'जयपुर में', [f'{c} में', 'दिल्ली में', 'मिस्र में']),
                     (f'{n} के परिवार में कितने लोग हैं?', 'पाँच', ['तीन', 'चार', 'छह']),
                     (f'{n} की मम्मी क्या काम करती हैं?', 'घर से ऑनलाइन हिंदी पढ़ाती हैं', ['अस्पताल में इंजीनियर हैं', 'दुकान चलाती हैं', 'स्कूल में खेल सिखाती हैं']),
                     ('मरियम कहाँ से है?', 'मिस्र से', ['जयपुर से', ctry + ' से', 'इंग्लैंड से'] if ctry != 'इंग्लैंड' else ['जयपुर से', 'कनाडा से', 'इंग्लैंड से']),
                     ('दादी शाम को क्या करती हैं?', 'राजस्थान की लोककथाएँ सुनाती हैं', ['बैडमिंटन खेलती हैं', 'चित्र बनाती हैं', 'हिंदी पढ़ाती हैं'])],
              vocab=[('शरारती', 'नटखट, शैतानी करने वाला', ['शांत', 'आलसी', 'डरपोक']), ('घर की जान', 'घर में सबसे प्रिय और रौनक लाने वाला व्यक्ति', ['घर की मालकिन', 'घर का सबसे बड़ा कमरा', 'घर की चौकीदार'])],
              tf=[(f'{n} बचपन से ही {c} में रहती है।', False, 'उसका जन्म जयपुर में हुआ; वह पिछले छह साल से वहाँ रहती है।'), (f'{n} का भाई उसे उदासी में हँसाता है।', True, 'वह चुटकुले सुनाकर हँसा देता है।')],
              infer=[(f'{n} और मरियम की दोस्ती की क्या विशेषता है?', 'वे अलग-अलग देशों की हैं और एक-दूसरे की भाषा के शब्द सीखती-सिखाती हैं — सांस्कृतिक आदान-प्रदान।'),
                     (f'{n} के भाई के व्यक्तित्व के बारे में दो बातें लिखिए।', 'शरारती है, पर दिल का अच्छा और बहन का ध्यान रखने वाला है।')],
              title=('विदेश में मेरा छोटा-सा भारत', ['बैडमिंटन का खेल', 'अस्पताल की नौकरी', 'अरबी भाषा']),
              points=[f'{n}, {age} वर्ष, जयपुर में जन्म', f'छह साल से {c} में', 'पाँच सदस्यों का परिवार', 'शरारती पर अच्छा भाई', 'दादी की लोककथाएँ', 'मिस्र की सहेली मरियम से भाषा का आदान-प्रदान'],
              evals=[(f'क्या आपको लगता है कि विदेश में रहते हुए भी {n} अपनी संस्कृति से जुड़ी है? पाठ से दो प्रमाण दीजिए।', 'हाँ: दादी की राजस्थानी लोककथाएँ, मम्मी का हिंदी पढ़ाना, सहेली को “धन्यवाद” सिखाना।')],
              notes={'परिवार': ['मम्मी — ऑनलाइन हिंदी शिक्षिका', 'पापा — अस्पताल में इंजीनियर', 'शरारती छोटा भाई', 'लोककथाएँ सुनाने वाली दादी'], 'रुचियाँ': ['चित्र बनाना', 'बैडमिंटन'], 'मित्रता': ['सहेली मरियम (मिस्र)', 'एक-दूसरे को भाषा सिखाना']})


def rd_profile2(r):
    n, g = name(r, 'm')
    text = (f'मैं {n} हूँ, कक्षा नौ का विद्यार्थी। हमारा परिवार संयुक्त परिवार है — दादा-दादी, चाचा-चाची, उनके दो बच्चे, मेरे माता-पिता और मेरी बड़ी बहन, सब एक ही घर में रहते हैं। '
            'कुल मिलाकर हम दस लोग हैं! इतने लोगों के साथ रहना कभी-कभी मुश्किल होता है — सुबह स्नानघर के लिए लंबी कतार लगती है। '
            'पर इसके फ़ायदे भी बहुत हैं। जब पिछले साल मुझे डेंगू हुआ था, तो हर कोई बारी-बारी से मेरी देखभाल करता था। '
            'मेरी बड़ी बहन मेडिकल की पढ़ाई कर रही है; वह बहुत गंभीर और मेहनती है। चाचा जी हँसमुख हैं और हर रविवार हमें क्रिकेट खिलाने ले जाते हैं। '
            'मेरा सबसे अच्छा दोस्त कबीर मेरे पड़ोस में रहता है। हम दोनों स्वभाव से बिल्कुल अलग हैं — मैं बातूनी हूँ और वह शर्मीला — फिर भी हमारी दोस्ती दस साल पुरानी है।')
