@t.add('C2', (2, 3, 4), 'explain')
def fest_two(r, D):
    P = frame_of(r, RD_FEST, 'read')
    m = mk('C2', D)
    a, b = r.sample(P['facts'], 2)
    stem = head(P) + f'संक्षेप में उत्तर दीजिए: {a[0]} और {b[0]}'
    return item(stem, f'{a[1]}; {b[1]}', f'प्रत्येक सही उत्तर {m // 2 if m >= 2 else 1} अंक', m, 'explain')


